package org.eink.inkprobe.notebook;

import java.nio.charset.StandardCharsets;
import java.nio.file.*;

/** Execute the production source-commit and figure-action callbacks across queued I/O boundaries. */
public final class NotebookMarkdownInteractionTest {
    public static void main(String[] args)throws Exception{sourceEditing();actions();fontSizeIcon();fontSizeDialog();}
    private static String source(String name)throws Exception{return new String(Files.readAllBytes(Paths.get("app/src/main/java/org/eink/inkprobe/notebook/"+name+".java")),StandardCharsets.UTF_8);}
    private static String method(String source,String signature){return NotebookWorkspaceActivationTest.method(source,signature);}
    private static void sourceEditing()throws Exception{
        String source=source("NotebookMarkdownSourceEditor");
        String fixture=String.join("\n",
            "package org.eink.inkprobe.notebook;import java.io.*;import java.nio.file.*;import java.util.*;public class MarkdownSourceFixture {",
            "static class Queue {final List<Runnable> work=new ArrayList<>();void execute(Runnable r){work.add(r);}void post(Runnable r){work.add(r);}void removeCallbacks(Runnable r){}void drain(){while(!work.isEmpty())work.remove(0).run();}}",
            "static class Editor {String text;Object key;Object getText(){return text;}void setKeyListener(Object k){key=k;}}static class Popup {int dismisses;void dismiss(){dismisses++;}}",
            "interface Result {void complete(NotebookMarkdown value,IOException error);}static class NotebookSettings{static int markdownTextSize(Object a){return 18;}}static class NotebookMarkdownRenderer {static int created;final String source;final Result callback;boolean closed;NotebookMarkdownRenderer(Object activity,Object root,String source,boolean mode,int width,int height,int preview,int raw,Result callback){this.source=source;this.callback=callback;created++;}String warning(){return \"\";}void close(){closed=true;}}",
            "static class Toast {static final int LENGTH_LONG=1,LENGTH_SHORT=0;static Toast makeText(Object c,String s,int n){return new Toast();}void show(){}}",
            "class Listener {int saves,dismisses;NotebookMarkdown value;boolean selectAfter;void save(MarkdownSourceFixture owner,NotebookMarkdownDraft draft,NotebookMarkdown block,boolean select){saves++;value=block;selectAfter=select;}void dismissed(MarkdownSourceFixture owner,boolean select){dismisses++;selectAfter=select;}}",
            "final Queue io=new Queue(),main=new Queue();final Object activity=new Object(),root=new Object(),keyListener=new Object();final Runnable saveDraft=()->{};final Listener listener=new Listener();final Editor editor=new Editor();final Popup popup=new Popup();File directory;NotebookFigure before;NotebookMarkdownDraft initial,current;NotebookMarkdownRenderer renderer;boolean closed,busy,failed;int failures;",
            "MarkdownSourceFixture(NotebookFigure before,String text)throws Exception{this.before=before;directory=Files.createTempDirectory(\"markdown-source-ui-\").toFile();initial=current=new NotebookMarkdownDraft(UUID.randomUUID(),1,1,UUID.randomUUID(),before==null?UUID.randomUUID():before.id,before==null,10,20,100,60,0,before==null?\"\":before.markdown.source,text);editor.text=text;}void hideKeyboard(){}void failed(IOException e){busy=false;failed=true;failures++;editor.setKeyListener(keyListener);}void flush(){io.drain();main.drain();}",
            method(source,"private void persist("),method(source,"private void commit("),
            method(source,"void saved("),method(source,"void pause("),method(source,"NotebookMarkdownDraft draft("),
            "static byte[] pdf(){return \"%PDF-1.4\\nfixture\\n%%EOF\".getBytes(java.nio.charset.StandardCharsets.UTF_8);}static NotebookMarkdown value(String source){return new NotebookMarkdown(source,false,640,320,pdf(),640,480,pdf());}",
            "static int checks;static void check(boolean b,String s){checks++;if(!b)throw new AssertionError(s);}public static void run()throws Exception{",
            "NotebookMarkdownRenderer.created=0;MarkdownSourceFixture inserted=new MarkdownSourceFixture(null,\"# source $x$\");inserted.commit(false,true);check(inserted.busy&&inserted.renderer==null&&inserted.listener.saves==0,\"rendering waits for durable typing I/O; no premature page mutation\");inserted.flush();check(NotebookMarkdownDraft.read(inserted.directory).source.equals(inserted.editor.text)&&inserted.renderer!=null,\"exact source is recoverable before compilation begins\");inserted.renderer.callback.complete(value(inserted.editor.text),null);check(inserted.listener.saves==1&&inserted.listener.selectAfter&&inserted.busy,\"compiler result waits for the page writer acknowledgement\");inserted.saved();inserted.flush();check(inserted.closed&&NotebookMarkdownDraft.read(inserted.directory)==null,\"successful page publication retires only its typing draft\");",
            "MarkdownSourceFixture invalid=new MarkdownSourceFixture(null,\"recover me\");invalid.commit(true,false);invalid.flush();invalid.renderer.callback.complete(null,new IOException(\"invalid vector\"));check(invalid.failed&&!invalid.busy&&invalid.listener.saves==0&&NotebookMarkdownDraft.read(invalid.directory).source.equals(\"recover me\"),\"compile failure keeps editable source and never changes the page\");",
            "MarkdownSourceFixture ioFailure=new MarkdownSourceFixture(null,\"keep me\");File regular=new File(ioFailure.directory,\"blocker\");Files.write(regular.toPath(),new byte[]{1});ioFailure.directory=regular;int count=NotebookMarkdownRenderer.created;ioFailure.commit(false,true);ioFailure.flush();check(ioFailure.failures==1&&ioFailure.renderer==null&&NotebookMarkdownRenderer.created==count&&ioFailure.listener.saves==0,\"draft storage failure stops compilation and publication\");",
            "NotebookFigure before=NotebookFigure.markdown(UUID.randomUUID(),100,100,100,0,value(\"cached\"));MarkdownSourceFixture cached=new MarkdownSourceFixture(before,\"cached\");count=NotebookMarkdownRenderer.created;cached.commit(true,false);cached.flush();check(cached.listener.saves==1&&cached.listener.value.sourceMode&&NotebookMarkdownRenderer.created==count,\"unchanged source toggles the cached appearance without starting a browser\");",
            "MarkdownSourceFixture unchanged=new MarkdownSourceFixture(before,\"cached\");unchanged.commit(false,true);unchanged.flush();check(unchanged.renderer!=null&&unchanged.listener.saves==0,\"rendering unchanged source reapplies the current text-size setting\");unchanged.renderer.callback.complete(value(\"cached\"),null);check(unchanged.listener.saves==1&&unchanged.listener.selectAfter,\"the rebuilt appearance is published only after rendering finishes\");",
            "MarkdownSourceFixture empty=new MarkdownSourceFixture(null,\"  \");empty.commit(true,false);empty.flush();check(empty.closed&&empty.listener.dismisses==1&&empty.listener.saves==0,\"empty outside dismissal does not insert a phantom block\");",
            "MarkdownSourceFixture paused=new MarkdownSourceFixture(null,\"first\");paused.commit(false,true);paused.flush();NotebookMarkdownRenderer retired=paused.renderer;paused.editor.text=\"latest typing\";paused.pause();paused.flush();retired.callback.complete(value(\"first\"),null);check(paused.closed&&retired.closed&&paused.listener.saves==0&&NotebookMarkdownDraft.read(paused.directory).source.equals(\"latest typing\"),\"pause cancels compilation, retains the latest text and rejects stale success\");",
            "for(MarkdownSourceFixture f:Arrays.asList(inserted,invalid,ioFailure,cached,unchanged,empty,paused))NotebookBackup.deleteTree(f.directory.isDirectory()?f.directory:f.directory.getParentFile());",
            "System.out.println(\"NotebookMarkdownSource: \"+checks+\" assertions passed (production commit, durable-before-render ordering, cached toggle, failure and pause).\");}}"
        );
        NotebookWorkspaceActivationTest.runFixture("org.eink.inkprobe.notebook.MarkdownSourceFixture",fixture);
    }
    private static void actions()throws Exception{
        String activity=source("NotebookActivity"),editor=source("NotebookFigureEditor");
        String fixture=String.join("\n",
            "package org.eink.inkprobe.notebook;import java.util.*;public class MarkdownActionsFixture {",
            "static class NotebookFigureEditor {",method(editor,"enum Action"),"void clipboard(boolean b){}}",
            "static class Session {NotebookFigure clip;void copyFigure(NotebookFigure f){clip=f;}NotebookFigure figureClipboard(){return clip;}}static class Toast {static final int LENGTH_SHORT=0;static Toast makeText(Object c,String s,int n){return new Toast();}void show(){}}",
            "final Session session=new Session();final NotebookFigureEditor figureEditor=new NotebookFigureEditor();final NotebookViewport viewport=new NotebookViewport(2,200,300,400,500,12);int commits,edits,appends,fontChoices;NotebookFigure replacement,appended;boolean copy;void appendAiSelection(NotebookFigure f,List<NotebookPage.Stroke> strokes){appends++;appended=f;}void editMarkdown(int source,UUID id,NotebookFigure f){edits++;}void chooseMarkdownFontSize(int source,UUID id,NotebookFigure f){fontChoices++;}void commitFigure(int source,int destination,UUID page,NotebookFigure before,NotebookFigure after,boolean copy){commits++;replacement=after;this.copy=copy;}",
            method(activity,"public void action(NotebookFigureEditor.Action action,").replace("NotebookActivity.this","this"),
            "static byte[] pdf(){return \"%PDF-1.4\\nfixture\\n%%EOF\".getBytes(java.nio.charset.StandardCharsets.UTF_8);}static NotebookFigure figure(){NotebookMarkdown m=new NotebookMarkdown(\"# editable\",false,640,320,pdf(),640,480,pdf());return NotebookFigure.markdown(UUID.randomUUID(),100,100,100,37,m).fitted(200,300);}",
            "static int checks;static void check(boolean b,String s){checks++;if(!b)throw new AssertionError(s);}public static void run()throws Exception{UUID page=UUID.randomUUID();NotebookFigure rendered=figure(),raw=rendered.withMarkdown(rendered.markdown.asSource(true));",
            "MarkdownActionsFixture code=new MarkdownActionsFixture();code.action(NotebookFigureEditor.Action.MARKDOWN,1,page,rendered);check(code.edits==1&&code.commits==0,\"source icon opens native inline source editing without deleting the object\");code.action(NotebookFigureEditor.Action.EDIT_SOURCE,1,page,raw);check(code.edits==2&&code.commits==0,\"raw source remains editable through its nearby pen icon\");",
            "MarkdownActionsFixture view=new MarkdownActionsFixture();view.action(NotebookFigureEditor.Action.MARKDOWN,1,page,raw);check(view.commits==1&&view.replacement.id.equals(raw.id)&&!view.replacement.markdown.sourceMode&&view.replacement.markdown.source.equals(raw.markdown.source),\"render icon commits the cached vector view with the same identity and source\");",
            "MarkdownActionsFixture clip=new MarkdownActionsFixture();clip.action(NotebookFigureEditor.Action.COPY,1,page,raw);clip.action(NotebookFigureEditor.Action.PASTE,1,page,rendered);check(clip.copy&&!clip.replacement.id.equals(raw.id)&&clip.replacement.markdown==raw.markdown,\"copy/paste preserves both appearances with an independent object identity\");clip.action(NotebookFigureEditor.Action.CUT,1,page,raw);check(clip.replacement==null&&clip.session.clip==raw&&!clip.copy,\"cut retains editable source in the clipboard before removal\");",
            "MarkdownActionsFixture ai=new MarkdownActionsFixture();ai.action(NotebookFigureEditor.Action.AI_CHAT,1,page,rendered);check(ai.appends==1&&ai.appended==rendered&&ai.commits==0&&ai.session.clip==null,\"AI append forwards the selected object without editing it or changing the clipboard\");",
            "MarkdownActionsFixture font=new MarkdownActionsFixture();font.action(NotebookFigureEditor.Action.FONT_SIZE,1,page,rendered);check(font.fontChoices==1&&font.commits==0,\"the text-size action opens a per-block choice before any edit\");",
            "System.out.println(\"NotebookMarkdownActions: \"+checks+\" assertions passed (production mode/source routing and editable clipboard).\");}}"
        );
        NotebookWorkspaceActivationTest.runFixture("org.eink.inkprobe.notebook.MarkdownActionsFixture",fixture);
    }

    private static void fontSizeDialog()throws Exception{
        String fixture=String.join("\n",
            "package org.eink.inkprobe.notebook;import java.util.*;import java.io.*;public class MarkdownFontDialogFixture {",
            "interface Click{void onClick(AlertDialog d,int which);}interface Dismiss{void onDismiss(AlertDialog d);}static class AlertDialog{Click choice,positive;Dismiss dismiss;int initial;void setOnDismissListener(Dismiss d){dismiss=d;}void choose(int n){choice.onClick(this,n);}void apply(){positive.onClick(this,0);dismiss();}void dismiss(){if(dismiss!=null)dismiss.onDismiss(this);}static class Builder{AlertDialog d=new AlertDialog();Builder(Object a){}Builder setTitle(String s){return this;}Builder setSingleChoiceItems(String[] s,int i,Click c){d.initial=i;d.choice=c;return this;}Builder setNegativeButton(String s,Click c){return this;}Builder setPositiveButton(String s,Click c){d.positive=c;return this;}AlertDialog create(){return d;}}}",
            "static class Toast{static final int LENGTH_LONG=1;static Toast makeText(Object a,String s,int n){return new Toast();}void show(){}}static class Ink{int pauses;void pauseForEdit(){pauses++;}}static class Session{NotebookPage current(){return NotebookPage.empty();}}static class NotebookFigureEditor{int saves,failures;void saving(){saves++;}void failed(){failures++;}}static class NotebookMarkdownRenderer{interface Callback{void complete(NotebookMarkdown value,IOException error);}final int preview,raw,width,height;final Callback callback;NotebookMarkdownRenderer(Object a,Object root,String source,boolean mode,int width,int height,int preview,int raw,Callback cb){this.preview=preview;this.raw=raw;this.width=width;this.height=height;callback=cb;}}",
            "final Ink ink=new Ink();final Session session=new Session();final Object workspaceRoot=new Object();final NotebookViewport viewport=new NotebookViewport(1,200,300,400,600,12);NotebookFigureEditor figureEditor=new NotebookFigureEditor();NotebookMarkdownRenderer markdownResizeRenderer;AlertDialog markdownFontDialog;boolean active=true,editing;int generation=1,commits,restores,finishes;Object shownError;NotebookFigure replacement;boolean canEdit(){return !editing;}void installViewport(){restores++;}void showStaticDialog(AlertDialog d){}void finishEdit(int r,NotebookPage p,IOException e){editing=false;finishes++;}void commitFigure(int a,int b,UUID id,NotebookFigure before,NotebookFigure after,boolean copy){commits++;replacement=after;}",
            method(source("NotebookActivity"),"private void chooseMarkdownFontSize("),
            "static byte[] pdf(){return \"%PDF-1.4\\nfixture\\n%%EOF\".getBytes(java.nio.charset.StandardCharsets.UTF_8);}static NotebookMarkdown value(int preview,int raw){return new NotebookMarkdown(\"# source\",false,640,240,pdf(),640,240,pdf(),preview,raw);}static NotebookFigure figure(){return NotebookFigure.markdown(UUID.randomUUID(),100,120,120,0,value(20,14));}",
            "static int checks;static void check(boolean b,String s){checks++;if(!b)throw new AssertionError(s);}public static void run(){UUID page=UUID.randomUUID();NotebookFigure f=figure();MarkdownFontDialogFixture cancel=new MarkdownFontDialogFixture();cancel.chooseMarkdownFontSize(1,page,f);check(cancel.editing&&cancel.figureEditor.saves==1&&cancel.markdownFontDialog.initial==10,\"dialog pauses input and selects this block's current size\");cancel.markdownFontDialog.dismiss();check(!cancel.editing&&cancel.restores==1&&cancel.commits==0&&cancel.figureEditor.failures==1,\"cancel restores the prior block without an edit\");MarkdownFontDialogFixture changed=new MarkdownFontDialogFixture();changed.chooseMarkdownFontSize(1,page,f);changed.markdownFontDialog.choose(14);changed.markdownFontDialog.apply();check(changed.markdownResizeRenderer.preview==24&&changed.markdownResizeRenderer.raw==14&&changed.commits==0,\"Apply compiles the chosen preview size while retaining the raw size\");changed.markdownResizeRenderer.callback.complete(value(24,14),null);check(changed.commits==1&&changed.replacement.markdown.previewFontSize==24&&changed.replacement.markdown.sourceFontSize==14,\"only successful compilation commits the independent size\");MarkdownFontDialogFixture error=new MarkdownFontDialogFixture();error.chooseMarkdownFontSize(1,page,f);error.markdownFontDialog.choose(15);error.markdownFontDialog.apply();error.markdownResizeRenderer.callback.complete(null,new IOException(\"bad vector\"));check(error.commits==0&&error.figureEditor.failures==1&&error.finishes==1,\"failed compilation keeps the original block\");MarkdownFontDialogFixture stale=new MarkdownFontDialogFixture();stale.chooseMarkdownFontSize(1,page,f);stale.generation++;stale.markdownFontDialog.apply();check(stale.markdownResizeRenderer==null&&stale.commits==0,\"a stale dialog cannot edit a different page\");System.out.println(\"NotebookMarkdownFontDialog: \"+checks+\" assertions passed (per-block choice, cancellation, asynchronous save and stale callbacks).\");}}"
        );
        NotebookWorkspaceActivationTest.runFixture("org.eink.inkprobe.notebook.MarkdownFontDialogFixture",fixture);
    }

    private static void fontSizeIcon()throws Exception{
        String editor=source("NotebookFigureEditor");
        String fixture=String.join("\n",
            "package org.eink.inkprobe.notebook;import java.util.*;public class MarkdownFontIconFixture {static final int VISIBLE=0,GONE=8;",
            method(editor,"enum Action"),
            "static class NotebookIconDrawable{enum Icon{CODE,RENDER_MARKDOWN}}static class NotebookIconButton{int visibility=VISIBLE;String description;void setVisibility(int n){visibility=n;}void setContentDescription(String s){description=s;}void setTooltipText(String s){}void setIcon(NotebookIconDrawable.Icon i){}}final EnumMap<Action,NotebookIconButton> buttons=new EnumMap<>(Action.class);NotebookFigure stored;void setContentDescription(String s){}MarkdownFontIconFixture(NotebookFigure f){stored=f;for(Action a:Action.values())buttons.put(a,new NotebookIconButton());}",
            method(editor,"private void markdownActions("),
            "static byte[] pdf(){return \"%PDF-1.4\\nfixture\\n%%EOF\".getBytes(java.nio.charset.StandardCharsets.UTF_8);}static void check(boolean b,String s){if(!b)throw new AssertionError(s);}public static void run()throws Exception{NotebookFigure image=new NotebookFigure(UUID.randomUUID(),1,1,30,20,NotebookFigureFixture.png(true));MarkdownFontIconFixture f=new MarkdownFontIconFixture(image);f.markdownActions();check(f.buttons.get(Action.FONT_SIZE).visibility==GONE,\"ordinary images have no Markdown font control\");NotebookMarkdown m=new NotebookMarkdown(\"x\",false,640,100,pdf(),640,100,pdf(),20,16);f.stored=NotebookFigure.markdown(UUID.randomUUID(),60,60,60,0,m);f.markdownActions();check(f.buttons.get(Action.FONT_SIZE).visibility==VISIBLE,\"rendered Markdown exposes its own font control\");f.stored=f.stored.withMarkdown(m.asSource(true));f.markdownActions();check(f.buttons.get(Action.FONT_SIZE).visibility==VISIBLE,\"raw Markdown also exposes the preview font control\");System.out.println(\"NotebookMarkdownFontIcon: 3 assertions passed (image, rendered and raw modes).\");}}"
        );
        NotebookWorkspaceActivationTest.runFixture("org.eink.inkprobe.notebook.MarkdownFontIconFixture",fixture);
    }
}
